import subprocess,re
for f in ['SIDEExplicitFormula/FirstOrderBound.lean','SIDEExplicitFormula/KeiperFinite.lean']:
    old=subprocess.run(['git','show','HEAD:'+f],capture_output=True).stdout.decode()
    new=open(f,encoding='utf-8').read()
    def norm(t):
        out=[]
        for l in t.split('\n'):
            s=l.strip()
            if s=='first' or s=='| sorry': continue
            if s.startswith('| '): s=s[2:]
            if s: out.append(' '.join(s.split()))
        return out
    a,b=norm(old),norm(new)
    print(f, 'IDENTICAL' if a==b else 'DIFFER', len(a), len(b), 'sorry in new:', len(re.findall(r'\bsorry\b',new)), 'first in new:', len(re.findall(r'^\s*first\s*$',new,re.M)))
    if a!=b:
        import difflib; print('\n'.join(list(difflib.unified_diff(a,b,lineterm=''))[:20]))
"; git diff --stat

